CREATE OR REPLACE FUNCTION public.fn_complete_transfer(p_transfer_id uuid, p_notes text, p_type text DEFAULT 'resolved'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    UPDATE public.conversation_transfers SET status = 'completed', resolution_notes = p_notes, resolution_type = p_type, completed_at = NOW()
    WHERE id = p_transfer_id AND status IN ('accepted', 'in_progress');
    RETURN FOUND;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_create_transfer(p_conversation_id uuid, p_from_agent_id uuid, p_to_agent_id uuid DEFAULT NULL::uuid, p_to_queue_id uuid DEFAULT NULL::uuid, p_transfer_type text DEFAULT 'direct'::text, p_priority text DEFAULT 'P3'::text, p_context_summary text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_transfer_id UUID;
BEGIN
    INSERT INTO public.conversation_transfers (
        conversation_id,
        from_agent_id,
        to_agent_id,
        to_queue_id,
        transfer_type,
        priority,
        context_summary,
        sla_deadline
    ) VALUES (
        p_conversation_id,
        p_from_agent_id,
        p_to_agent_id,
        p_to_queue_id,
        p_transfer_type,
        p_priority,
        p_context_summary,
        CASE 
            WHEN p_priority = 'P1' THEN NOW() + INTERVAL '15 minutes'
            WHEN p_priority = 'P2' THEN NOW() + INTERVAL '1 hour'
            WHEN p_priority = 'P3' THEN NOW() + INTERVAL '4 hours'
            ELSE NOW() + INTERVAL '24 hours'
        END
    ) RETURNING id INTO v_transfer_id;
    
    RETURN v_transfer_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_create_transfer(p_source_instance text, p_target_instance text, p_remote_jid text, p_reason text, p_category text, p_priority integer DEFAULT 2, p_transfer_type text DEFAULT 'internal'::text, p_source_operator text DEFAULT NULL::text, p_context_summary text DEFAULT NULL::text, p_tags text[] DEFAULT '{}'::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_transfer_id UUID;
BEGIN
    INSERT INTO public.conversation_transfers (
        source_instance, target_instance, remote_jid,
        reason, category, priority, transfer_type, source_operator,
        context_summary, tags, status, expires_at
    ) VALUES (
        p_source_instance, p_target_instance, p_remote_jid,
        p_reason, p_category, p_priority, p_transfer_type, p_source_operator,
        p_context_summary, p_tags, 'pending',
        CASE 
            WHEN p_priority = 4 THEN NOW() + INTERVAL '2 hours'
            WHEN p_priority = 3 THEN NOW() + INTERVAL '4 hours'
            WHEN p_priority = 2 THEN NOW() + INTERVAL '8 hours'
            ELSE NOW() + INTERVAL '24 hours'
        END
    ) RETURNING id INTO v_transfer_id;

    RETURN v_transfer_id;
END;
$function$
;

