 RETURNS TABLE(category text, total bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT category, COUNT(*)::bigint AS total
  FROM public.audio_memes
