CREATE OR REPLACE FUNCTION public.manage_department_member(p_profile_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, _admin_user_id uuid DEFAULT NULL::uuid, _target_profile_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_target_id UUID;
BEGIN
    v_target_id := COALESCE(p_profile_id, _target_profile_id);
    
    IF v_target_id IS NULL THEN
        RETURN FALSE;
    END IF;

    IF p_action = 'add' AND p_department_id IS NOT NULL THEN
        UPDATE public.profiles SET department_id = p_department_id WHERE id = v_target_id;
    ELSIF p_action = 'remove' THEN
        UPDATE public.profiles SET department_id = NULL WHERE id = v_target_id;
    END IF;
    RETURN TRUE;
END;
$function$
;

