CREATE OR REPLACE FUNCTION public.rpc_dlq_list_audit(p_limit integer DEFAULT 100)
 RETURNS SETOF dlq_audit_log
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'supervisor')) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM public.dlq_audit_log ORDER BY created_at DESC LIMIT p_limit;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.rpc_dlq_list_audit(p_limit integer, p_offset integer, p_action text)
 RETURNS TABLE(id uuid, action text, entity_id text, details jsonb, created_at timestamp with time zone, user_id uuid, user_name text, user_email text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'supervisor')) THEN
    PERFORM public.log_rls_denied('dlq_audit_log', 'admin|supervisor',
      jsonb_build_object('rpc', 'rpc_dlq_list_audit', 'action', p_action));
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT al.id,
         al.action::text,
         al.entity_id::text,
         al.details,
         al.created_at,
         al.user_id,
         p.name AS user_name,
         p.email AS user_email
  FROM public.audit_logs al
  LEFT JOIN public.profiles p ON p.user_id = al.user_id
  WHERE al.entity_type = 'failed_messages'
    AND (p_action IS NULL OR p_action = 'all' OR al.action = p_action)
  ORDER BY al.created_at DESC
  LIMIT COALESCE(p_limit, 30)
  OFFSET COALESCE(p_offset, 0);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.rpc_dlq_log_item_action(p_item_id uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    INSERT INTO public.dlq_audit_log (item_id, action, reason, performed_by)
    VALUES (p_item_id, p_action, p_reason, auth.uid());
    
    IF p_action = 'delete' THEN
        DELETE FROM public.failed_messages WHERE id = p_item_id;
    END IF;
    
    RETURN TRUE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.rpc_dlq_log_item_action(p_item_id uuid DEFAULT NULL::uuid, p_action text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF p_ids IS NOT NULL THEN
        INSERT INTO public.dlq_audit_log (item_id, action, reason, performed_by)
        SELECT id, p_action, p_reason, auth.uid() FROM unnest(p_ids) as id;
    ELSIF p_item_id IS NOT NULL THEN
        INSERT INTO public.dlq_audit_log (item_id, action, reason, performed_by)
        VALUES (p_item_id, p_action, p_reason, auth.uid());
    END IF;
    RETURN TRUE;
END;
$function$
;

