CREATE OR REPLACE FUNCTION public.rpc_instance_auth_event_summary(p_instance text)
 RETURNS TABLE(event_type text, total bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN QUERY
    SELECT instance_auth_events.event_type, count(*) as total
    FROM public.instance_auth_events
    WHERE (p_instance IS NULL OR instance_name = p_instance)
    GROUP BY 1;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.rpc_instance_auth_event_trend(p_instance text, p_hours integer DEFAULT 24)
 RETURNS TABLE(bucket timestamp with time zone, instance_name text, success_count bigint, failure_count bigint, invalid_signature bigint, auth_401 bigint, auth_403 bigint, total bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        date_trunc('hour', created_at) as bucket,
        COALESCE(instance_auth_events.instance_name, 'all'),
        count(*) FILTER (WHERE event_type = 'auth.success') as success_count,
        count(*) FILTER (WHERE event_type = 'auth.failure') as failure_count,
        count(*) FILTER (WHERE event_type = 'auth.invalid_signature') as invalid_signature,
        count(*) FILTER (WHERE event_type = 'auth.401') as auth_401,
        count(*) FILTER (WHERE event_type = 'auth.403') as auth_403,
        count(*) as total
    FROM public.instance_auth_events
    WHERE (p_instance IS NULL OR instance_auth_events.instance_name = p_instance)
      AND created_at > now() - (p_hours || ' hours')::interval
    GROUP BY 1, 2 ORDER BY 1;
END;
$function$
;

