CREATE OR REPLACE FUNCTION public.rpc_list_failed_messages(p_status text[], p_instance text, p_search text, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer)
 RETURNS TABLE(id uuid, instance_name text, message_id text, error_message text, retry_count integer, next_retry_at timestamp with time zone, status text, created_at timestamp with time zone, total_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'supervisor')) THEN
    PERFORM public.log_rls_denied('failed_messages', 'admin|supervisor',
      jsonb_build_object('rpc', 'rpc_list_failed_messages', 'filters',
        jsonb_build_object('status', p_status, 'instance', p_instance, 'search', p_search)));
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT fm.id, fm.instance_name, fm.message_id, fm.error_message,
         fm.retry_count, fm.next_retry_at, fm.status, fm.created_at,
         COUNT(*) OVER()::bigint AS total_count
  FROM public.failed_messages fm
  WHERE (p_status IS NULL OR fm.status = ANY(p_status))
    AND (p_instance IS NULL OR fm.instance_name = p_instance)
    AND (p_search IS NULL OR fm.error_message ILIKE '%'||p_search||'%' OR fm.message_id ILIKE '%'||p_search||'%')
    AND (p_from IS NULL OR fm.created_at >= p_from)
    AND (p_to IS NULL OR fm.created_at <= p_to)
  ORDER BY fm.created_at DESC
  LIMIT COALESCE(p_limit, 50)
  OFFSET COALESCE(p_offset, 0);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.rpc_list_transfers_paginated(p_status text DEFAULT NULL::text, p_priority integer DEFAULT NULL::integer, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, source_instance text, target_instance text, remote_jid text, contact_name text, status text, priority integer, transfer_type text, category text, reason text, from_agent_id uuid, to_agent_id uuid, sla_deadline timestamp with time zone, created_at timestamp with time zone, accepted_at timestamp with time zone, completed_at timestamp with time zone, total_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT t.id, t.source_instance, t.target_instance, t.remote_jid, t.contact_name,
         t.status, t.priority, t.transfer_type, t.category, t.reason,
         t.from_agent_id, t.to_agent_id, t.sla_deadline,
         t.created_at, t.accepted_at, t.completed_at,
         COUNT(*) OVER()::bigint AS total_count
  FROM public.conversation_transfers t
  WHERE (p_status IS NULL OR t.status = p_status)
    AND (p_priority IS NULL OR t.priority = p_priority)
    AND (p_from IS NULL OR t.created_at >= p_from)
    AND (p_to IS NULL OR t.created_at <= p_to)
  ORDER BY t.created_at DESC
  LIMIT COALESCE(p_limit, 50)
  OFFSET COALESCE(p_offset, 0);
$function$
;

